<?php
require __DIR__.'/auth.php';require __DIR__.'/db.php';require_once __DIR__.'/transfers.php';require_permission('budget.view');
$year=(int)($_GET['year']??$_POST['fiscal_year']??fiscal_year_for_date());$unit=is_admin()?(int)($_GET['unit_id']??0):current_unit_id();$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 try{begin_financial_transaction($conn);if(($_POST['action']??'save')==='cancel')round2_cancel($conn,(int)($_POST['id']??0),trim($_POST['reason']??''));elseif(($_POST['action']??'save')==='edit')round2_edit($conn,(int)($_POST['id']??0),$_POST);else round2_create($conn,$_POST);$conn->commit();header('Location: transfer_round2.php?year='.$year.'&unit_id='.$unit.'&saved=1');exit;}
 catch(Throwable $e){$conn->rollback();if($e->getCode()===403)http_response_code(403);$error=operation_error($e);}
}
$stmt=$conn->prepare('SELECT ca.*,bt.doc_no FROM control_accounts ca JOIN budget_transfers bt ON bt.id=ca.source_transfer_id WHERE ca.fiscal_year=? AND ca.cancelled_at IS NULL AND bt.cancelled_at IS NULL'.($unit>0?' AND ca.unit_id=?':'').' ORDER BY ca.id DESC');$unit>0?$stmt->bind_param('ii',$year,$unit):$stmt->bind_param('i',$year);$stmt->execute();$accounts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$stmt=$conn->prepare('SELECT bd.*,ca.budget_code FROM budget_disbursements bd LEFT JOIN control_accounts ca ON ca.source_transfer_id=bd.source_transfer_id WHERE bd.fiscal_year=?' . (isset($_GET['show_cancelled'])?'':' AND bd.cancelled_at IS NULL').($unit>0?' AND bd.unit_id=?':'').' ORDER BY bd.id DESC');$unit>0?$stmt->bind_param('ii',$year,$unit):$stmt->bind_param('i',$year);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>รายงานเบิกรอบ 2</title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php require __DIR__.'/../template/nav.php';?><main class="container"><section class="panel"><h1 class="page-title">รายการโอนครั้งที่ 2 / รายงานเบิก</h1><p>รายงานเบิกนี้บันทึกตัดจ่ายในบัญชีคุมงบประมาณ โดยตรง หากบันทึกผ่านฎีกาแล้วไม่ต้องบันทึกรายการเดียวกันซ้ำที่หน้านี้</p><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="get" class="toolbar"><input type="number" name="year" value="<?=$year?>"><label><input type="checkbox" name="show_cancelled" value="1" <?=isset($_GET['show_cancelled'])?'checked':''?>> แสดงรายการที่ลบแล้ว</label><button class="btn btn-primary">เลือกปี</button></form></section>
<?php if(has_permission('round2.manage')):?><section class="panel"><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="fiscal_year" value="<?=$year?>"><div class="form-grid form-grid-2"><label>บัญชีคุม / เอกสารต้นทาง</label><select name="source_transfer_id" required><option value="">-- เลือก --</option><?php foreach($accounts as $account):?><option value="<?=$account['source_transfer_id']?>"><?=htmlspecialchars($account['budget_code'].' / '.$account['doc_no'])?> · ใช้ได้ <?=number_format(ledger_available_cents($account['received_amount'],ledger_totals($conn,(int)$account['id']))/100,2)?></option><?php endforeach;?></select><label>เลขรายงาน</label><input name="report_no" required><label>วันที่รายงาน</label><input type="date" name="report_date" value="<?=date('Y-m-d')?>" required><label>รายละเอียด</label><textarea name="description" maxlength="255" required></textarea><label>จำนวนเงิน</label><input type="number" name="amount" min="0.01" step="0.01" required></div><button class="btn btn-success">บันทึกตัดจ่าย</button></form></section><?php endif;?>
<section class="panel"><table><tr><th>รายงาน</th><th>วันที่</th><th>รหัสงบประมาณ</th><th>รายละเอียด</th><th>จำนวนเงิน</th><th>สถานะ / จัดการ</th></tr><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['report_no'])?></td><td><?=htmlspecialchars($row['report_date'])?></td><td><?=htmlspecialchars($row['budget_code']??'')?></td><td><?=htmlspecialchars($row['description'])?></td><td><?=number_format((float)$row['amount'],2)?></td><td><?=$row['cancelled_at']?'ยกเลิกแล้ว':($row['ledger_entry_id']?'ผูกบัญชีแล้ว':'รอกระทบยอด')?><br><?php if(!$row['cancelled_at']&&has_permission('round2.manage')):?><details <?=(int)($_GET['edit']??0)===(int)$row['id']?'open':''?>><summary>แก้ไขรายการ</summary><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="fiscal_year" value="<?=$year?>"><div class="form-field"><label>เลขรายงาน</label><input name="report_no" maxlength="50" value="<?=htmlspecialchars($row['report_no'])?>" required></div><div class="form-field"><label>วันที่</label><input type="date" name="report_date" value="<?=htmlspecialchars($row['report_date'])?>" required></div><div class="form-field"><label>รายละเอียด</label><textarea name="description" maxlength="255" required><?=htmlspecialchars($row['description'])?></textarea></div><div class="form-field"><label>จำนวนเงิน</label><input name="amount" type="number" min="0.01" step="0.01" value="<?=htmlspecialchars($row['amount'])?>" required></div><div class="form-field"><label>เหตุผลแก้ไข</label><input name="reason" minlength="5" maxlength="255" required></div><button class="btn btn-success">บันทึกการแก้ไข</button></form></details><details><summary>ลบรายการ</summary><form method="post"><?=csrf_field()?><?=request_field()?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$row['id']?>"><input type="hidden" name="fiscal_year" value="<?=$year?>"><input name="reason" minlength="5" maxlength="255" required placeholder="เหตุผล"><button class="btn btn-danger" onclick="return confirm('ยืนยันลบและคืนยอดงบ?')">ยืนยันลบรายการ</button></form></details><?php endif;?></td></tr><?php endforeach;?></table></section></main></body></html>
